from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlsplit
import hashlib, json, re

class ProfileParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.ignored = 0
        self.text = []
        self.routes = []
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.ignored += 1
        if tag == 'a' and not self.ignored:
            href = dict(attrs).get('href') or ''
            try:
                url = urlsplit(href)
            except ValueError:
                return
            if url.scheme in {'http', 'https'} and (('northern' in (url.hostname or '').lower()) or ('contact' in url.path.lower() and not url.query)):
                self.routes.append(url._replace(query='', fragment='').geturl())
            elif not url.netloc and 'contact' in url.path.lower():
                self.routes.append(url.path)
    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.ignored:
            self.ignored -= 1
    def handle_data(self, data):
        if not self.ignored and data.strip():
            self.text.append(' '.join(data.split()))

source = Path('products/services/northern-catalogue-pilot/raw/shopify-partner-profile.html')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '4bef471ba12bfba841252f8d7228cfd2a495e82d903341dda0bd285ec60add14', digest
parser = ProfileParser()
parser.feed(raw.decode('utf-8'))
keywords = re.compile(r'catalog(?:ue)?|product data|product feed|data migrat|product migrat|sku|replatform|northern commerce|contact partner', re.I)
hits = [{'fragment': i, 'text': text[:650], 'previous': parser.text[i-1][:180] if i else '', 'next': parser.text[i+1][:180] if i+1 < len(parser.text) else ''} for i,text in enumerate(parser.text) if keywords.search(text)]
result = {'source_task':'TASK-179570700200','source_sha256':digest,'visible_text_fragments':len(parser.text),'matching_fragment_count':len(hits),'matching_fragments':hits[:40],'candidate_public_links':list(dict.fromkeys(parser.routes))[:20],'limits':'Visible text triage only. Verify authorship, claims and route in context. Links are candidates, and generic labels establish no specific capability or demand.'}
output = source.parent.parent / 'director-profile-workflow-excerpts.json'
